
(function(){
  var sec=document.getElementById("tarify"); if(!sec) return;
  var tM=document.getElementById("tMonth"),tY=document.getElementById("tYear");
  var year=false;
  function fmt(n){return n.toLocaleString("ru-RU");}
  function r10(n){return Math.round(n/10)*10;}
  function upd(){
    var mult=year?0.8:1, disc=Math.round((1-mult)*100);
    [].forEach.call(sec.querySelectorAll(".pcard"),function(c){
      var amt=c.querySelector(".amt"),old=c.querySelector(".old"),b=c.querySelector(".pbadge"),per=c.querySelector(".pper");
      var base=+amt.getAttribute("data-base"), price=r10(base*mult);
      amt.textContent=fmt(price)+"\u00a0\u20bd";
      if(mult<1){old.textContent=fmt(base)+"\u00a0\u20bd";old.style.display="";b.textContent="Выгода -"+disc+"%";b.classList.remove("hide");}
      else{old.textContent="";old.style.display="none";b.classList.add("hide");}
      per.textContent=year?"в месяц при оплате за год":"в месяц";
    });
  }
  tM.addEventListener("click",function(){year=false;tM.classList.add("on");tY.classList.remove("on");upd();});
  tY.addEventListener("click",function(){year=true;tY.classList.add("on");tM.classList.remove("on");upd();});
  upd();
})();



(function(){
  var ANS1="Мария, спасибо за тёплый отзыв и высокую оценку! Рады, что вы оценили свежесть устриц, крабовый тар-тар и внимание нашей команды. Будем рады снова видеть вас на Арбате в «Волне»!";
  var reduce=matchMedia("(prefers-reduced-motion:reduce)").matches;
  var $=function(id){return document.getElementById(id);};
  var scDash=$("scDash"),scRev=$("scRev"),winUrl=$("winUrl"),winBody=$("winBody");
  var replyBox=$("replyBox"),replyTA=$("replyTA"),cc=$("cc"),btnSend=$("btnSend"),foot1=$("foot1");
  var ans1=$("ans1"),ans1body=$("ans1body"),ans2=$("ans2"),ans3=$("ans3");
  var autoSw=$("autoSw"),autoStat=$("autoStat"),ansWith=$("ansWith"),ansWithout=$("ansWithout");
  var btnReply=$("btnReply"),cursor=$("cursor"),pauseHint=$("pauseHint"),kpiTotal=$("kpiTotal"),revList=$("revList");
  var cur=0,paused=false,timers=[],typer=null,firstLoad=true;
  function mob(){return matchMedia("(max-width:820px)").matches;}
  function scrollRev(){if(mob()){revList.style.transform="";return;}var amt=Math.max(0,revList.scrollHeight-(winBody.clientHeight-34));revList.style.transform="translateY(-"+amt+"px)";}

  function ct(){timers.forEach(clearTimeout);timers=[];if(typer){clearInterval(typer);typer=null;}}
  function T(fn,ms){var t=setTimeout(fn,ms);timers.push(t);return t;}
  function url(p){winUrl.textContent="app.dailygrow.ru/"+p;}
  function show(which,delay){var d=which==="dash";scDash.classList.toggle("active",d);scRev.classList.toggle("active",!d);scDash.classList.toggle("off",!d);scRev.classList.toggle("off",d);animBars(d?scDash:scRev,delay);}
  function animBars(el,delay){var fs=el.querySelectorAll("[data-w]");[].forEach.call(fs,function(f){f.style.width="0";});var run=function(){[].forEach.call(fs,function(f){f.style.width=f.getAttribute("data-w");});};if(delay){T(run,delay);}else{requestAnimationFrame(function(){requestAnimationFrame(run);});}}
  function hideAns(a){a.classList.remove("show");a.hidden=true;}
  function showAns(a){a.hidden=false;requestAnimationFrame(function(){requestAnimationFrame(function(){a.classList.add("show");});});}

  function resetReviews(){
    replyBox.hidden=true;replyTA.innerHTML="";cc.textContent="0 из 2500 символов";btnSend.disabled=false;btnSend.innerHTML="Отправить";
    foot1.style.display="";btnReply.classList.remove("flash");
    hideAns(ans1);hideAns(ans2);hideAns(ans3);
    autoSw.classList.remove("on","flash");autoStat.classList.remove("show");
    ansWith.textContent="2 280";ansWithout.textContent="138";
    kpiTotal.classList.remove("flash");cursor.style.opacity="0";
    revList.style.transform="translateY(0)";
  }
  function esc(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;");}
  function type(cb){var i=0;replyTA.innerHTML="";typer=setInterval(function(){i+=1;if(i>ANS1.length)i=ANS1.length;replyTA.innerHTML=esc(ANS1.slice(0,i))+'<span class="caret"></span>';cc.textContent=i+" из 2500 символов";if(i>=ANS1.length){clearInterval(typer);typer=null;replyTA.textContent=ANS1;cc.textContent=ANS1.length+" из 2500 символов";cb&&cb();}},24);}

  function clickEl(el,sxf,syf,cb){
    if(reduce||!el){cb&&cb();return;}
    var wbr=winBody.getBoundingClientRect(),r=el.getBoundingClientRect();
    var x=r.left-wbr.left+Math.min(46,r.width/2),y=r.top-wbr.top+r.height/2;
    cursor.style.transition="none";cursor.style.left=(wbr.width*sxf)+"px";cursor.style.top=(wbr.height*syf)+"px";cursor.style.opacity="0";
    requestAnimationFrame(function(){cursor.style.opacity="1";cursor.style.transition="";requestAnimationFrame(function(){cursor.style.left=x+"px";cursor.style.top=y+"px";});});
    T(function(){cursor.classList.add("press");el.classList.add("flash");},1050);
    T(function(){cursor.classList.remove("press");},1200);
    T(function(){cursor.style.opacity="0";el.classList.remove("flash");cb&&cb();},1500);
  }

  function enter(i){
    if(i===0){
      var fl=firstLoad;firstLoad=false;
      resetReviews();show("dash",fl?620:0);url("dashboard");
      if(paused)return;
      T(function(){clickEl(kpiTotal,.82,.08,function(){if(!paused)go(1);});},fl?3200:1500);
    }else if(i===1){
      resetReviews();show("rev");url("reviews");
      if(paused)return;
      T(function(){clickEl(btnReply,.5,.42,function(){if(!paused)go(2);});},900);
    }else if(i===2){
      show("rev");url("reviews");foot1.style.display="none";replyBox.hidden=false;hideAns(ans1);replyTA.innerHTML="";
      if(reduce){ans1body.textContent=ANS1;replyBox.hidden=true;showAns(ans1);if(!paused)T(function(){go(3);},1200);}
      else{T(function(){if(!paused)type(function(){if(!paused)T(function(){advanceToPublish();if(!paused)T(function(){go(3);},2600);},700);});},900);}
    }else{
      show("rev");url("reviews");foot1.style.display="none";
      ans1body.textContent=ANS1;replyBox.hidden=true;ans1.hidden=false;ans1.classList.add("show");
      if(paused)return;
      T(function(){clickEl(autoSw,.45,.4,function(){
        autoSw.classList.add("on");autoStat.classList.add("show");
        T(function(){showAns(ans2);ansWith.textContent="2 281";ansWithout.textContent="137";},400);
        T(function(){showAns(ans3);ansWith.textContent="2 282";ansWithout.textContent="136";},1250);
        if(!paused)T(function(){go(0);},4400);
      });},600);
    }
  }
  function advanceToPublish(){
    ans1body.textContent=ANS1;btnSend.disabled=true;btnSend.innerHTML='<span class="spin"></span>Публикуем…';
    T(function(){replyBox.hidden=true;showAns(ans1);ansWith.textContent="2 280";},700);
  }
  function go(i){cur=((i%4)+4)%4;ct();enter(cur);}

  function pauseToggle(){
    if(paused){paused=false;pauseHint.classList.remove("show");go(cur);}
    else{paused=true;ct();if(typer){clearInterval(typer);typer=null;}pauseHint.classList.add("show");}
  }
  winBody.addEventListener("click",pauseToggle);
  go(0);
})();


(function(){
  var feed=document.getElementById("minifeed"); if(!feed) return;
  var PL={ya:"data:image/webp;base64,",gis:"data:image/webp;base64,",goo:"data:image/webp;base64,"};
  var data=[["gis","Игорь П.","★★★★★","Лучший сет морепродуктов в городе"],
            ["ya","Анна С.","★★★★★","Свежайшие устрицы, обязательно вернёмся"],
            ["goo","Мария Л.","★★★★☆","Вкусно, но столик ждали минут десять"],
            ["ya","Павел Р.","★★★★★","Гребешки и креветки выше похвал"],
            ["gis","Ольга Н.","★★★★☆","Атмосфера супер, порции могли быть больше"],
            ["goo","Денис К.","★★★★★","Виды из окон и кухня на высоте"]];
  var i=0,timer=null,reduce=matchMedia("(prefers-reduced-motion:reduce)").matches;
  // Собираем одну строку отзыва; animate=true даёт эффект вылета сверху
  function makeRow(d,animate){
    var row=document.createElement("div"); row.className=animate?"mrow ins":"mrow";
    row.innerHTML='<img src="'+PL[d[0]]+'" alt=""><div class="mc"><div class="mn">'+d[1]+'<span class="ms">'+d[2]+'</span></div><div class="mt">'+d[3]+'</div></div>';
    return row;
  }
  function add(){
    var d=data[i%data.length]; i++;
    var row=makeRow(d,!reduce);
    feed.insertBefore(row,feed.firstChild);
    if(!reduce){requestAnimationFrame(function(){requestAnimationFrame(function(){row.classList.remove("ins");});});}
    while(feed.children.length>3){feed.removeChild(feed.lastChild);}
  }
  // По умолчанию сразу показываем 3 отзыва (без анимации вылета)
  function prefill(){ feed.innerHTML=""; for(var k=0;k<3;k++){ var d=data[i%data.length]; i++; feed.appendChild(makeRow(d,false)); } }
  function start(){ if(timer||reduce)return; add(); timer=setInterval(add,3400); } // обновление только при наведении
  function stop(){ if(timer){clearInterval(timer);timer=null;} }
  prefill();
  var card=feed.closest(".dcard")||feed;
  card.addEventListener("mouseenter",start);
  card.addEventListener("mouseleave",stop);
  // Автозапуск: один раз добавить пару новых отзывов
  card.__play=function(){var n=0;(function once(){if(n++>=2||reduce)return;add();setTimeout(once,650);})();};
})();

(function(){
  // Карточка «Мгновенные уведомления»: лента как в «Сбор отзывов», иконки каналов Max/Telegram/Bitrix24
  var feed=document.getElementById("notifFeed"); if(!feed) return;
  var IC={max:"https://cdn.jsdelivr.net/gh/webdailygrow/icons@main/max.webp",
          tg:"https://cdn.jsdelivr.net/gh/webdailygrow/icons@main/telegram.webp",
          b24:"https://cdn.jsdelivr.net/gh/webdailygrow/icons@main/bitrix24.webp"};
  // Недельный отчёт (в CRM) и алерты о новых отзывах (в Max/Telegram)
  var REPORT=["b24","Недельный отчёт в CRM","","+42 отзыва · рейтинг 4,9 ↑"];
  var reviews=[
    ["tg","Новый отзыв","★★★★★","Волна Арбатская"],
    ["max","Новый отзыв","★★★★★","Волна Москва-Сити"],
    ["tg","Новый отзыв","★★★★☆","Волна на Пресне"],
    ["max","Новый отзыв","★★★★★","Волна в Сокольниках"],
    ["tg","Новый отзыв","★★★★★","Волна в Крылатском"]
  ];
  var ri=0,timer=null,reduce=matchMedia("(prefers-reduced-motion:reduce)").matches;
  function nextReview(){var d=reviews[ri%reviews.length];ri++;return d;}
  function makeRow(d,animate){
    var row=document.createElement("div"); row.className=animate?"mrow ins":"mrow";
    if(d[0]==="b24"){ // подробный недельный отчёт в CRM
      row.className+=" report";
      row.innerHTML='<img src="'+IC.b24+'" alt=""><div class="mc"><div class="mn">'+d[1]+'</div><div class="mt">'+d[3].replace("↑",'<span class="up-ar">↑</span>')+'</div></div>';
    }else{ // новый отзыв: оценка + филиал
      var stars='<span class="ms" style="color:#ffb400">'+d[2]+'</span>';
      row.innerHTML='<img src="'+IC[d[0]]+'" alt=""><div class="mc"><div class="mn">'+d[1]+stars+'</div><div class="mt">'+d[3]+'</div></div>';
    }
    return row;
  }
  function add(){ var row=makeRow(nextReview(),!reduce); feed.insertBefore(row,feed.firstChild);
    if(!reduce){requestAnimationFrame(function(){requestAnimationFrame(function(){row.classList.remove("ins");});});}
    while(feed.children.length>3){ // держим 3 строки, но недельный отчёт всегда остаётся снизу
      var rm=null; for(var n=feed.children.length-1;n>=0;n--){ if(!feed.children[n].classList.contains("report")){rm=feed.children[n];break;} }
      feed.removeChild(rm||feed.lastChild);
    } }
  // Снизу — недельный отчёт (отправлен раньше), сверху свежие отзывы
  function prefill(){ feed.innerHTML=""; feed.appendChild(makeRow(nextReview(),false)); feed.appendChild(makeRow(nextReview(),false)); feed.appendChild(makeRow(REPORT,false)); }
  function start(){ if(timer||reduce)return; add(); timer=setInterval(add,3400); }
  function stop(){ if(timer){clearInterval(timer);timer=null;} }
  prefill();
  var card=feed.closest(".dcard")||feed;
  card.addEventListener("mouseenter",start);
  card.addEventListener("mouseleave",stop);
  // Автозапуск: один раз показать новый отзыв (отчёт остаётся снизу)
  card.__play=function(){if(!reduce)add();};
})();

(function(){
  var root=document.getElementById("aa"); if(!root) return;
  var rev=document.getElementById("aaRev"),ic=document.getElementById("aaIc");
  var ans=document.getElementById("aaAns"),ansH=document.getElementById("aaAnsH"),ansB=document.getElementById("aaAnsB");
  var REPLY="Анна, спасибо за тёплый отзыв! Рады, что устрицы и подача впечатлили. Ждём вас снова!";
  // Логотип площадки берём из уже отрисованного отзыва (чтобы не вставлять data-URI повторно)
  var srcEl=document.querySelector("#card1 .pl-ic")||document.querySelector(".plat-row img");
  if(srcEl&&ic) ic.src=srcEl.getAttribute("src");
  var reduce=matchMedia("(prefers-reduced-motion:reduce)").matches,tms=[],typer=null,running=false;
  function clr(){tms.forEach(clearTimeout);tms=[];if(typer){clearInterval(typer);typer=null;}}
  function T(fn,ms){var t=setTimeout(fn,ms);tms.push(t);return t;}
  function esc(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;");}
  function type(str,cb){var i=0;ansB.innerHTML="";typer=setInterval(function(){i++;if(i>str.length)i=str.length;ansB.innerHTML=esc(str.slice(0,i))+'<span class="gcaret"></span>';if(i>=str.length){clearInterval(typer);typer=null;ansB.textContent=str;cb&&cb();}},28);}
  // Состояние покоя: отзыв и уже опубликованный ответ (без анимации)
  function rest(){clr();rev.classList.remove("in");ans.classList.add("show");ansB.textContent=REPLY;ansH.textContent="✓ Опубликовано";}
  function cycle(){
    clr();
    ans.classList.remove("show"); ansB.innerHTML=""; ansH.textContent="⚙ Ответ ИИ";
    rev.classList.add("in"); // прячем отзыв, чтобы показать его появление
    requestAnimationFrame(function(){requestAnimationFrame(function(){ rev.classList.remove("in"); });}); // 1) отзыв появляется
    T(function(){ ans.classList.add("show");                                                               // 2) окно ответа
      T(function(){ type(REPLY,function(){ ansH.textContent="✓ Опубликовано"; if(running)T(cycle,2600); }); },350); // 3) генерация -> опубликовано
    },400);
  }
  rest(); // по умолчанию показываем готовый результат
  var card=root.closest(".dcard")||root;
  card.__play=function(){if(reduce)return;running=false;cycle();}; // автозапуск один раз
  if(!reduce){
    card.addEventListener("mouseenter",function(){running=true;cycle();}); // сценарий только при наведении
    card.addEventListener("mouseleave",function(){running=false;rest();});
  }
})();

(function(){
  // Карточка SEO: печать ответа с подсветкой ключевых слов
  var box=document.getElementById("seoTxt"); if(!box) return;
  var card=box.closest(".dcard");
  function esc(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;");}
  // Части ответа: k:true — ключевое слово (выделяется)
  var PARTS=[
    {t:"Спасибо за отзыв о ",k:false},
    {t:"ресторане морепродуктов на Арбате",k:true},
    {t:"! Ждём снова за ",k:false},
    {t:"свежими устрицами в Москве",k:true},
    {t:".",k:false}
  ];
  function htmlUpto(pi,ci){
    var h="";
    for(var j=0;j<pi;j++){var p=PARTS[j];h+=p.k?'<em>'+esc(p.t)+'</em>':esc(p.t);}
    var cur=PARTS[pi];
    if(cur){var sub=esc(cur.t.slice(0,ci));h+=cur.k?'<em>'+sub+'</em>':sub;}
    return h;
  }
  var FULL=htmlUpto(PARTS.length,0);
  var bars=card.querySelector(".sv-bars"),svN=document.getElementById("svN"),svD=document.getElementById("svD");
  var reduce=matchMedia("(prefers-reduced-motion:reduce)").matches,typer=null,tms=[],running=false,cntTimer=null;
  function clr(){if(typer){clearInterval(typer);typer=null;}tms.forEach(clearTimeout);tms=[];if(cntTimer){clearInterval(cntTimer);cntTimer=null;}}
  function countUp(from,to,dur){if(cntTimer)clearInterval(cntTimer);var steps=Math.max(1,Math.round(dur/40)),k=0;cntTimer=setInterval(function(){k++;var p=Math.min(1,k/steps);if(svN)svN.textContent=Math.round(from+(to-from)*p);if(p>=1){clearInterval(cntTimer);cntTimer=null;}},40);}
  // 24, столбики свёрнуты, % скрыт — пока печатается ответ
  function visitStart(){if(cntTimer){clearInterval(cntTimer);cntTimer=null;}if(svN)svN.textContent="24";if(svD)svD.style.opacity="0";if(bars)bars.classList.add("low");}
  // ответ допечатан: 24->108, показываем +27%, столбики растут
  function visitGrow(){if(bars)bars.classList.remove("low");if(svD)svD.style.opacity="1";countUp(24,108,1100);}
  // итог (покой)
  function visitFinal(){if(cntTimer){clearInterval(cntTimer);cntTimer=null;}if(svN)svN.textContent="108";if(svD)svD.style.opacity="1";if(bars)bars.classList.remove("low");}
  function rest(){clr();box.innerHTML=FULL;visitFinal();}
  function type(){
    clr();var pi=0,ci=0;box.innerHTML='<span class="gcaret"></span>';
    visitStart();
    typer=setInterval(function(){
      ci++;
      if(PARTS[pi]&&ci>PARTS[pi].t.length){pi++;ci=0;}
      if(pi>=PARTS.length){clearInterval(typer);typer=null;box.innerHTML=FULL;
        visitGrow();
        if(running)tms.push(setTimeout(type,2800));return;}
      box.innerHTML=htmlUpto(pi,ci)+'<span class="gcaret"></span>';
    },26);
  }
  rest();
  card.__play=function(){if(reduce)return;running=false;type();}; // автозапуск один раз
  if(!reduce){
    card.addEventListener("mouseenter",function(){running=true;type();});
    card.addEventListener("mouseleave",function(){running=false;rest();});
  }
})();

(function(){
  // Карточка «Удаление негатива»: отзыв -> жалоба по правилам -> удалён и исчезает
  var root=document.getElementById("del"); if(!root) return;
  var rev=document.getElementById("delRev"),ic=document.getElementById("delIc");
  var ans=document.getElementById("delAns"),ansH=document.getElementById("delAnsH"),ansB=document.getElementById("delAnsB");
  var COMPLAINT="Отзыв нарушает правила площадки: скрытая реклама конкурента. Направили жалобу на удаление.";
  var srcEl=document.querySelector(".plat-row img"); if(srcEl&&ic) ic.src=srcEl.getAttribute("src");
  var reduce=matchMedia("(prefers-reduced-motion:reduce)").matches,tms=[],typer=null,running=false;
  function clr(){tms.forEach(clearTimeout);tms=[];if(typer){clearInterval(typer);typer=null;}}
  function T(fn,ms){var t=setTimeout(fn,ms);tms.push(t);return t;}
  function esc(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;");}
  function type(str,cb){var i=0;ansB.innerHTML="";typer=setInterval(function(){i++;if(i>str.length)i=str.length;ansB.innerHTML=esc(str.slice(0,i))+'<span class="gcaret"></span>';if(i>=str.length){clearInterval(typer);typer=null;ansB.textContent=str;cb&&cb();}},22);}
  // Покой: показываем итог — жалоба отправлена, отзыв удалён
  function rest(){clr();rev.classList.remove("in");rev.classList.add("removed");ans.classList.add("show","done");ansB.textContent=COMPLAINT;ansH.textContent="✓ Отзыв удалён";}
  function cycle(){
    clr();
    rev.classList.remove("removed"); ans.classList.remove("show","done"); ansB.innerHTML=""; ansH.textContent="⚠ Жалоба по правилам площадки";
    rev.classList.add("in"); // 1) плохой отзыв появляется
    requestAnimationFrame(function(){requestAnimationFrame(function(){ rev.classList.remove("in"); });});
    T(function(){ ans.classList.add("show");                 // 2) пишется жалоба
      T(function(){ type(COMPLAINT,function(){
        ansH.textContent="✓ Отзыв удалён"; ans.classList.add("done");  // 3) удалён
        T(function(){ rev.classList.add("removed"); if(running)T(cycle,2800); },600); // отзыв исчезает
      }); },400);
    },1050);
  }
  rest();
  var card=root.closest(".dcard")||root;
  card.__play=function(){if(reduce)return;running=false;cycle();}; // автозапуск один раз
  if(!reduce){
    card.addEventListener("mouseenter",function(){running=true;cycle();});
    card.addEventListener("mouseleave",function(){running=false;rest();});
  }
})();

(function(){
  // Карточка «Суммаризация»: рост полосок по классу (hover + автозапуск)
  var tone=document.querySelector(".sum-tone"); if(!tone) return;
  var card=tone.closest(".dcard"); var reduce=matchMedia("(prefers-reduced-motion:reduce)").matches;
  function play(){ if(reduce)return; card.classList.remove("sumplay"); void card.offsetWidth; card.classList.add("sumplay"); }
  // автозапуск: один проход, затем снять класс (если не наводят мышкой)
  card.__play=function(){ play(); setTimeout(function(){ if(!card.matches(":hover"))card.classList.remove("sumplay"); },3300); };
  if(!reduce){
    card.addEventListener("mouseenter",play);
    card.addEventListener("mouseleave",function(){card.classList.remove("sumplay");});
  }
})();

(function(){
  // Последовательный автозапуск анимаций по 1 разу при появлении секции
  if(matchMedia("(prefers-reduced-motion:reduce)").matches)return;
  var sec=document.querySelector(".diff"); if(!sec)return;
  var cards=[].slice.call(document.querySelectorAll(".diff .dcard"));
  var done=false,io=null;
  function playAll(){ if(done)return; done=true; if(io)io.disconnect(); var first=cards[0], rest=cards.slice(1); if(first&&first.__play)first.__play(); setTimeout(function(){ rest.forEach(function(c,i){ setTimeout(function(){ if(c.__play)c.__play(); }, i*1200); }); }, 1400); }
  // Запуск, когда секция реально попадает в зону видимости
  function checkVisible(){ var r=sec.getBoundingClientRect(); if(r.top<innerHeight*0.85&&r.bottom>0) playAll(); }
  if("IntersectionObserver" in window){
    io=new IntersectionObserver(function(en){en.forEach(function(x){if(x.isIntersecting)playAll();});},{threshold:.2});
    io.observe(sec);
  }
  window.addEventListener("load",function(){setTimeout(checkVisible,300);});
  document.addEventListener("visibilitychange",function(){if(!document.hidden)setTimeout(checkVisible,120);});
  setTimeout(checkVisible,600);
})();

(function(){
  var els=[].slice.call(document.querySelectorAll(".reveal"));
  if(!els.length)return;
  if(!("IntersectionObserver" in window)){els.forEach(function(e){e.classList.add("in");});return;}
  var io=new IntersectionObserver(function(en){en.forEach(function(x){if(x.isIntersecting){x.target.classList.add("in");io.unobserve(x.target);}});},{threshold:.15});
  els.forEach(function(e){io.observe(e);});
})();

